script:
/* Write your CSS here */
:root{--red:#EE2435;--bg:#FFFFFF;--soft:#F1F5F9;--card:#FFFFFF;--text:#1e2b3a;--muted:#4b5a6b;--line:#dbe3ec;--head:#011E41;--cf:#d6e2f0;--cfh:#9db8d8}
@media (prefers-color-scheme:dark){:root{--bg:#0c1622;--soft:#121f2f;--card:#172538;--text:#e6edf5;--muted:#9fb0c3;--line:#26384d;--head:#cfe0f5;--cf:#1e3a5c;--cfh:#2f5a8f}}
.mapsec *,.dir *{box-sizing:border-box}
.mapsec{font-family:Figtree,Arial,sans-serif;color:var(--text)}
.wrap{max-width:1180px;margin:0 auto;padding:0 24px}
.mapsec{padding:56px 0 64px}
.mh{display:flex;align-items:center;gap:12px;margin-bottom:24px}
.mh svg{width:38px;height:38px}
.mh h2{font-size:clamp(24px,3vw,34px);color:var(--head)}
.mapgrid{display:grid;grid-template-columns:1.5fr 1fr;gap:24px;align-items:start}
@media(max-width:900px){.mapgrid{grid-template-columns:1fr}}
.mapbox{position:relative;background:var(--soft);border-radius:16px;overflow:hidden;height:clamp(420px,72vh,660px)}
#map{width:100%;height:100%;display:block;cursor:grab;touch-action:pan-y}
.cty{fill:var(--cf);stroke:var(--card);stroke-width:1.2;cursor:pointer;outline:none;transition:fill .12s}
.cty:hover{fill:var(--cfh)}
.cty:focus-visible{stroke:var(--red);stroke-width:3}
.cty.sel{fill:var(--red)}
.lbl{display:none;font:600 9px Figtree,Arial,sans-serif;fill:var(--head);text-anchor:middle;pointer-events:none;paint-order:stroke;stroke:var(--soft);stroke-width:2px}
.zl .lbl{display:block}
.zc{position:absolute;top:12px;right:12px;display:grid;gap:6px}
.zc button{width:42px;height:42px;border:1px solid var(--line);background:var(--card);color:var(--head);border-radius:10px;font:700 20px Figtree,Arial,sans-serif;cursor:pointer}
.zc button:hover{border-color:var(--red)}
.pcard{background:var(--card);border:1px solid var(--line);border-top:4px solid var(--red);border-radius:16px;padding:24px}
.pcard h3{font-size:24px;color:var(--head);margin-bottom:8px}
.pcard p{margin:0 0 10px}.pcard .m{color:var(--muted);font-size:15px}
.pcard a{color:var(--head);font-weight:600}
.legend{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-top:18px}
.legend h4{margin:0 0 12px;font:800 16px "Bricolage Grotesque",Arial,sans-serif;color:var(--head)}
.legend ul{list-style:none;margin:0;padding:0;display:grid;gap:8px;font-size:15px}
.legend li{display:flex;align-items:center;gap:10px}
.sw{width:18px;height:18px;border-radius:4px;flex:none}
.legend .n{color:var(--muted);font-size:14px;margin:12px 0 0}
.dir{background:var(--soft);padding:56px 0 80px}
.dir h2{font-size:clamp(26px,3.5vw,38px);color:var(--head);margin-bottom:20px}
.dir input{width:100%;max-width:520px;padding:14px 16px;border:1px solid var(--line);border-radius:10px;background:var(--card);color:var(--text);font:inherit}
.dir input::placeholder{color:var(--muted)}
.cnt{color:var(--muted);font-size:15px;margin:14px 0}
.dgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:14px;list-style:none;margin:0;padding:0}
.dc{background:var(--card);border:1px solid var(--line);border-left:4px solid var(--red);border-radius:12px;padding:14px 16px;display:flex;justify-content:space-between;align-items:center;gap:10px}
.dc b{display:block;font:700 18px "Bricolage Grotesque",Arial,sans-serif;color:var(--head)}
.dc small{color:var(--muted)}
.dc button{border:1px solid var(--head);background:transparent;color:var(--head);border-radius:8px;padding:7px 12px;font:600 14px Figtree,Arial,sans-serif;cursor:pointer;white-space:nowrap}
.dc button:hover{background:var(--head);color:var(--bg)}
.none{background:var(--card);border-top:4px solid var(--red);border-radius:12px;padding:32px;text-align:center;color:var(--muted)}
